from pathlib import Path
import json
root=Path('/workspace/sites/olympiad-atlas')
links=json.loads((root/'research/americas/cms-links.json').read_text())
files={}
for x in links:
 u=x['href'];n=u.split('/')[-1]
 if '.pdf' in n:files[n]=u
out=[]
def add(year,num,diff,topic,tags,statement,reason,solfile,probfile,page=1,aliases=[],competition='CMO'):
 u=files[solfile]+f'#page={page}'
 out.append(dict(id=f'ca-{competition.lower()}-{year}-{num}',country='Canada',competition=competition,year=year,number=str(num),statement=statement,solution=f'[View the official worked solution PDF, page {page}]({u}).',sourceUrl=files[probfile],solutionUrl=u,solutionKind='source-link',topic=topic,tags=tags.split('|'),difficulty=diff,ratingReason=reason,reviewStatus='individually-assessed',notes='Mathematical statement restated in original wording. Official solution reviewed; linked rather than reproduced.',appearances=[dict(competition=competition,year=year,number=str(num))]+[dict(competition=c,year=year,number=str(n)) for c,n in aliases]))
add(2021,2,4.5,'Combinatorics','Permutations|Induction|Modular arithmetic',r'How many permutations $(a_1,\ldots,a_n)$ of $1,\ldots,n$ have the following property: for every $k\in\{1,\ldots,n\}$, the residues of $a_1,\ldots,a_k$ modulo $k$ are all different?', 'The essential insight is to work backwards: each prefix must be an interval of consecutive integers, and the next deletion removes an endpoint. This yields a clean binary choice count, but the reverse induction is not immediately suggested.', '2021CJMO_solutions_en.pdf','CJMO-2021-questions-en.pdf',2,competition='CJMO')
add(2021,2,4,'Algebra','Inequalities|AM–GM|Telescoping products',r'For $n\ge2$, let positive reals $a_1,\ldots,a_n$ satisfy $\sum_{i=1}^n a_i=2^n-1$. Determine the minimum of $\displaystyle\sum_{k=1}^n\frac{a_k}{1+\sum_{i=1}^{k-1}a_i}$.','Adding one to each summand turns the expression into ratios of successive partial sums. Their product telescopes, so AM–GM and the equality case complete the proof; discovering that reformulation is the main hurdle.','2021CMO_solutions_en-1.pdf','CMO-2021-questions-en-4.pdf',2,[('CJMO',4)])
add(2021,3,7,'Combinatorics','Circular arrangements|Double counting|Extremal arguments',r'$N$ hosts and $N$ guests sit around a circular table, where $N\ge4$. Two guests talk if at most one person separates them, or if exactly two people separate them and at least one of those two is a host. Prove that at least $N$ pairs of guests talk.','A run decomposition is useful, but naive counting loses too much at singleton runs. A successful proof tracks several run lengths and compensates for the exceptional configurations; the bookkeeping adds substantial difficulty.','2021CMO_solutions_en-1.pdf','CMO-2021-questions-en-4.pdf',3)
add(2021,4,7,'Number Theory','Functional equations|GCD|Prime powers',r'Call $f:\mathbb Z_{>0}\to\mathbb Z_{>0}$ admissible when $\gcd(f(f(x)),f(x+y))=\gcd(x,y)$ for all positive integers $x,y$. Determine precisely which positive integers $m$ must satisfy $f(m)=m$ for every admissible $f$.','Requires combining divisor-forcing substitutions with a contradiction involving the second iterate. The exceptional prime powers then need an explicit swap construction, so both necessity and sufficiency involve separate insights.','2021CMO_solutions_en-1.pdf','CMO-2021-questions-en-4.pdf',4,[('CJMO',5)])
add(2022,1,4.5,'Algebra','Radicals|Identities|Sign analysis',r'Real numbers $a,b$ satisfy $ab+\sqrt{ab+1}+\sqrt{a^2+b}\sqrt{b^2+a}=0$. Find, with proof, the value of $a\sqrt{b^2+a}+b\sqrt{a^2+b}$.','Squaring the rearranged hypothesis produces the square of the desired expression. The remaining sign is not automatic: the opposite signs of a and b must be used carefully.','cmo2022-solutions-en.pdf','2022CMO-exam-en.pdf',1,[('CJMO',3)])
add(2022,2,5,'Number Theory','Divisor function|Double counting|Parity',r'Write $d(m)$ for the number of positive divisors of $m$. Prove that $\displaystyle\sum_{k=1}^n d(2k-1)\le\sum_{k=1}^n d(2k)$ for every positive integer $n$.','Termwise comparison fails. Reversing the order of counting to count multiples of each divisor reveals that odd divisors have at most a one-unit imbalance, paid for by the even divisor 2.','cmo2022-solutions-en.pdf','2022CMO-exam-en.pdf',2,[('CJMO',4)])
add(2022,3,6.5,'Combinatorics','Induction|Processes|Bounds',r'Start with $n\ge2$ copies of 1. At each step replace two numbers $a,b$ by either $a+b$ or $\min(a^2,b^2)$. Let $f(n)$ be the largest attainable final number after $n-1$ steps. Prove $2^{n/3}<f(n)\le3^{n/3}$.','The process must first be expressed through a split recurrence. The upper bound needs the small summand cases controlled, while the strict lower bound is best proved by strengthening it before induction.','cmo2022-solutions-en.pdf','2022CMO-exam-en.pdf',3,[('CJMO',5)])
add(2022,4,5.5,'Combinatorics','Colouring|Geometry|Modular arithmetic',r'$n$ distinct lines, no three concurrent, partition the plane. Every region must receive one label from $\{A_1,A_2\}$ and one from $\{B_1,B_2,B_3\}$. Regions sharing an edge must differ in both labels, and all six label-pairs must occur. Determine all $n$ for which this can be done for every such line arrangement.','A sharp obstruction comes from parallel lines. For sufficiency, orienting the lines and counting which side contains a region provides a single integer whose residues modulo 2 and 3 simultaneously produce both colourings.','cmo2022-solutions-en.pdf','2022CMO-exam-en.pdf',6)
add(2023,1,5,'Number Theory','Primes|Decision trees|Extremal arguments',r'A secret integer lies in $\{1,\ldots,50\}$. Each question chooses a positive integer $m$ and asks whether $m$ divides the secret number. Answers are truthful and later questions may depend on previous answers. Determine the smallest worst-case number of questions needed to identify the number.','The lower bound comes from the all-no branch and the primes, not the usual binary information bound. Matching it requires a deliberate small-prime query strategy and a finite case count.','cmo2023-solutions-en.pdf','2023CMO-exam-en.pdf',1,[('CJMO',3)])
add(2023,2,4.5,'Combinatorics','Graph theory|Double counting|Processes',r'A class has 20 students; each has exactly three friends within the class, and friendship is mutual. Initially five have bought a concert ticket. Subsequently a student buys a ticket whenever at least two friends already have one. Can all 20 eventually buy tickets?', 'A monotone edge count or counting the friendships used by each new buyer proves impossibility. The subtle point is exploiting the final buyer, who has three rather than merely two earlier neighbours.','cmo2023-solutions-en.pdf','2023CMO-exam-en.pdf',2,[('CJMO',4)])
add(2023,3,6.5,'Geometry','Nine-point circle|Ptolemy|Inequalities',r'In acute triangle $ABC$, altitudes $AD,BE,CF$ meet at $H$. The circle through $D,E,F$ meets the three altitude lines again at $X,Y,Z$, respectively. Prove $\displaystyle\frac{AH}{DX}+\frac{BH}{EY}+\frac{CH}{FZ}\ge3$.','The nine-point circle converts the denominators into full circumcircle chords. A second transformation using Ptolemy expresses the ratios as a/(b+c), reducing the problem to Nesbitt; coordinating these two geometric ideas is the challenge.','cmo2023-solutions-en.pdf','2023CMO-exam-en.pdf',3,[('CJMO',5)])
add(2024,1,4,'Geometry','Reflections|Incenter|Perpendicular bisectors',r'Let $I$ be the incenter of triangle $ABC$. Reflect line $AB$ in line $CI$, and reflect line $AC$ in line $BI$. If the two reflected lines meet at $X$, prove $XI\perp BC$.','Reflecting A into two points on BC turns the intended perpendicular into a perpendicular-bisector statement. Two equal-distance observations finish the argument once those auxiliary points are identified.','cmo2024-solutions-en.pdf','CMO2024-problems.pdf',1,[('CJMO',3)])
add(2024,2,4.5,'Number Theory','Factorials|Prime valuations|Parity',r'Can positive integers be placed at 2024 positions around a circle so that the products at adjacent positions, counted cyclically, are exactly $1!,2!,\ldots,2024!$ in some order?', 'Multiplying all adjacent products gives a square. Detecting the contradiction requires a suitable prime valuation or reducing the factorial product to a square times 1012!, rather than testing individual placements.','cmo2024-solutions-en.pdf','CMO2024-problems.pdf',2,[('CJMO',4)])
add(2024,3,5.5,'Algebra','Polynomials|Involutions|Parity',r'Count the ten-digit positive integers $d_9d_8\cdots d_0$ for which $d_9x^9+d_8x^8+\cdots+d_0$ is irreducible over $\mathbb Q$. Prove that this count is even.','Digit reversal suggests a pairing, but it must be shown to preserve irreducibility, and every fixed point must be excluded using the odd degree and the root -1. This is an inventive algebraic involution.','cmo2024-solutions-en.pdf','CMO2024-problems.pdf',3,[('CJMO',5)])
add(2024,4,6.5,'Combinatorics','Information|Double counting|Grid constructions',r'One cell of an $M\times N$ grid, with $M,N\ge2$, is marked. A detector tests whether the marked cell lies in a chosen axis-parallel rectangular subgrid. All detectors must be chosen before any answers are received. Determine the minimum number of detectors that always identifies the marked cell.','The construction is accessible once the one-dimensional problem is understood. The matching lower bound requires counting distinguishability along all four boundary rows and columns without overcounting a detector.','cmo2024-solutions-en.pdf','CMO2024-problems.pdf',4)
add(2025,2,6,'Number Theory','Exponential Diophantine equations|Factorisation|Primes',r'Find all positive integer quadruples $(a,b,c,p)$ satisfying $2^ap^b=(p+2)^c-1$, where both $p$ and $p+2$ are odd primes.','Factorisation first forces p+1 to be a power of 2, and a modulo-3 argument fixes p. Resolving the remaining exponential equation needs a second factorisation with gcd and parity restrictions.','CMO2025-solutions.pdf','CMO2025-problems.pdf',4,[('CJMO',4)])
add(2025,3,6.5,'Algebra','Reciprocal polynomials|Constructive identities',r'A polynomial $s(x)=\sum_{i=0}^d c_ix^i$ is called reflexive if for some integer $m\ge d$ its coefficients satisfy $c_i=c_{m-i}$ for $0\le i\le m$, with $c_i=0$ for $i>d$. Given $\ell\ge2$ and $p\in\mathbb Z[x]$, prove that reflexive $q,r\in\mathbb Z[x]$ exist with $(1+x+\cdots+x^{\ell-1})p(x)=q(x)+x^\ell r(x)$.','Translating coefficient symmetry into x^m s(1/x)=s(x) suggests a constructive identity, but the candidate numerators and division by x-1 must be engineered and checked for integrality and the correct symmetry.','CMO2025-solutions.pdf','CMO2025-problems.pdf',5,[('CJMO',5)])
add(2025,2,5,'Geometry','Radical axes|Cyclic quadrilaterals|Concurrency',r'In trapezoid $ABCD$, $AB\parallel CD$ and $BC\ne DA$. A circle through $C,D$ meets the lines $AC,AD,BC,BD$ again at $W,X,Y,Z$, respectively. Prove that $WZ,XY,AB$ are concurrent.','Two auxiliary cyclic quadrilaterals arise from the parallel sides. Recognising the three desired lines as radical axes makes the concurrency immediate, but that circle structure has to be discovered.','CJMO2025-solutions.pdf','CJMO2025-problems.pdf',1,competition='CJMO')
add(2026,1,4.5,'Combinatorics','Lattice points|Symmetry|Double sums',r'For coprime integers $a,b\ge2$, let $S$ be the integer-coordinate points strictly inside the triangle with vertices $(0,0),(a,0),(0,b)$. Evaluate $\displaystyle\sum_{(x,y)\in S}(a-2x)(b-2y)$ and justify your answer.','Completing the triangle to a rectangle makes the sum factor. Central reflection preserves each summand and exchanges the two triangular halves; coprimality is essential to avoid unpaired points on the diagonal.','CMO2026-solutions.pdf','CMO2026-problems.pdf',1,[('CJMO',3)])
add(2026,2,6,'Number Theory','Divisibility|Pigeonhole principle|Induction',r'Coins have distinct positive integer denominations $d_1,\ldots,d_n$. Does there always exist a positive integer $D$ such that, for every positive integer $k$, any collection of these coins worth $kD$ can be partitioned into $k$ groups each worth $D$?', 'A common multiple alone is not the most convenient construction. Taking a sufficiently large multiple allows extraction of equal-value packets; a floor-sum bound then provides enough packets for an inductive partition.','CMO2026-solutions.pdf','CMO2026-problems.pdf',5,[('CJMO',4)])
add(2026,3,5.5,'Combinatorics','Hamiltonian cycles|Averaging|Minimax',r'An adversary marks $2n^2$ cells of a $2n\times2n$ grid. After seeing the marks, a walker chooses a path visiting every cell exactly once using shared-edge moves, and labels its successive cells $1,2,\ldots,4n^2$. The score is the sum of the labels on marked cells. The walker minimises this score; the adversary maximises it. Determine the guaranteed score in terms of $n$.','Checkerboard placement supplies the lower bound. The matching upper bound uses a Hamiltonian cycle traversed in both directions from a marked cell, an effective but non-obvious averaging choice.','CMO2026-solutions.pdf','CMO2026-problems.pdf',7,[('CJMO',5)])
add(2026,4,6.5,'Geometry','Solid geometry|Volume ratios|Incenter',r'A tetrahedron $ABCD$ has an insphere with centre $I$, and every interior dihedral angle is acute. Suppose $\displaystyle\frac{\operatorname{vol}(IABC)}{BC}=\frac{\operatorname{vol}(IACD)}{CD}=\frac{\operatorname{vol}(IADB)}{DB}$. Prove that $AI$ is perpendicular to plane $BCD$.','The volume ratios must be interpreted in two different ways: they identify both AI’s intersection with the base and A’s perpendicular projection as the base triangle’s incenter. The acute-angle hypothesis must be used to select the interior equidistant point.','CMO2026-solutions.pdf','CMO2026-problems.pdf',9)
(root/'data/americas.json').write_text(json.dumps(out,ensure_ascii=False,indent=2))
ratings={
 'CMO-2021':[3,4,7,7,9], 'CJMO-2021':[2.5,4.5,3,4,7],
 'CMO-2022':[4.5,5,6.5,5.5,8.5], 'CJMO-2022':[3,3.5,4.5,5,6.5],
 'CMO-2023':[5,4.5,6.5,7.5,7.5], 'CJMO-2023':[3.5,3,5,4.5,6.5],
 'CMO-2024':[4,4.5,5.5,6.5,8], 'CJMO-2024':[3,3,4,4.5,5.5],
 'CMO-2025':[8,6,6.5,7.5,8.5], 'CJMO-2025':[2.5,5,8,6,6.5],
 'CMO-2026':[4.5,6,5.5,6.5,8.5], 'CJMO-2026':[2.5,3,4.5,6,5.5]}
coverage={'scope':'Americas','fullyScreened':[{'competition':k.rsplit('-',1)[0],'year':int(k.rsplit('-',1)[1]),'ratings':v,'source':'https://cms.math.ca/competitions/cmo/'} for k,v in ratings.items()], 'papersScreened':len(ratings),'problemAppearancesScreened':60,'uniqueIncluded':len(out),'gaps':['CMO before 2021 and CJMO 2020 not yet reviewed.','United States and Latin American sources in progress.'],'method':'Individual statement-and-solution review. Excluded problems outside 4–7; common CMO/CJMO problems deduplicated with appearances preserved. Ratings are subjective estimates, not official scores.'}
(root/'research/americas-coverage.json').write_text(json.dumps(coverage,ensure_ascii=False,indent=2))
print('saved',len(out))
